321	+  /** A session's shop requests this second: false once over the cap. */
322	+  private withinShopRate(sessionId: string): boolean {
323	+    const frame = this.simulation.frame;
324	+    const rate = this.shopRate.get(sessionId) ?? { windowStart: frame, count: 0 };
325	+    if (frame - rate.windowStart >= STEPS_PER_SECOND) {
326	+      rate.windowStart = frame;
327	+      rate.count = 0;
328	+    }
329	+    rate.count++;
330	+    this.shopRate.set(sessionId, rate);
331	+    return rate.count <= MAX_SHOP_MESSAGES_PER_SECOND;
332	+  }
