334	+  /**
335	+   * A shop request arrives. An id this player already had decided is answered from the room's record first, whatever
336	+   * holds now (a retry never pays twice or drinks twice). Otherwise, while the match runs, it waits for a world tick:
337	+   * merged into a pending request with its id, or refused `busy` when two already wait.
338	+   */
339	+  private arriveShop(sessionId: string, requestId: string, kind: "purchase" | "use"): void {
340	+    const client = this.clients.get(sessionId);
341	+    if (kind === "purchase") {
342	+      const earlier = this.tonicPurchases.decided(sessionId, requestId);
343	+      const answer = (decision: TonicPurchaseDecision, replayed: boolean) => client?.send(ShopMessageType.TonicPurchase, tonicPurchaseMessage(requestId, decision, replayed));
344	+      if (earlier !== undefined) answer(earlier, true);
345	+      else if (!this.inPlay()) answer({ outcome: "refused", reason: "not-in-play" }, false);
346	+      else if (this.tonicPurchases.arrive(sessionId, requestId) === "busy") answer({ outcome: "refused", reason: "busy" }, false);
347	+      return;
348	+    }
349	+    const earlier = this.tonicUses.decided(sessionId, requestId);
350	+    const answer = (decision: TonicUseDecision, replayed: boolean) => client?.send(ShopMessageType.TonicUsed, tonicUsedMessage(requestId, decision, replayed));
