943	+/** At most this many requests of one kind wait per player; more are refused `busy` and kept nowhere. */
944	+export const MAX_PENDING_SHOP_REQUESTS = 2;
945	+/** The refusals of one kind kept per player for replays (the oldest goes first), as the ledger keeps its own. */
946	+export const KEPT_SHOP_REFUSALS = 16;
947	+
948	+interface PlayerRequests<D> {
949	+  readonly pending: PendingShopRequest[];
950	+  /** Every applied request id, never evicted (bounded by gold, or by the tonics bought). */
951	+  readonly applied: Map<string, D>;
952	+  /** The last `KEPT_SHOP_REFUSALS` refused request ids, oldest first. */
953	+  readonly refused: Map<string, D>;
954	+}
955	+
956	+/**
957	+ * One kind of shop request (tonic purchases, or drinks), per player, by the client's request id (§16): an id already
958	+ * decided is answered from `decided` first; one still pending is merged into it (one answer); at most
959	+ * `MAX_PENDING_SHOP_REQUESTS` wait per player, and the room takes one per player per world tick, oldest first.
960	+ */
961	+export class ShopBook<D extends { readonly outcome: string }> {
962	+  private readonly books = new Map<string, PlayerRequests<D>>();
963	+
964	+  private bookOf(playerId: string): PlayerRequests<D> {
965	+    let book = this.books.get(playerId);
966	+    if (book === undefined) {
967	+      book = { pending: [], applied: new Map(), refused: new Map() };
968	+      this.books.set(playerId, book);
969	+    }
970	+    return book;
971	+  }
972	+
973	+  /** The room's earlier decision on this (player, request id), if it kept one. */
974	+  decided(playerId: string, requestId: string): D | undefined {
975	+    const book = this.books.get(playerId);
976	+    return book?.applied.get(requestId) ?? book?.refused.get(requestId);
977	+  }
978	+
979	+  /** A request arrives whose id this player has no decision for (the caller replays those first). */
980	+  arrive(playerId: string, requestId: string): "merged" | "busy" | "queued" {
981	+    const book = this.bookOf(playerId);
