1006	+
1007	+  /** Keeps a decision for replays: every applied one, and the player's last refusals. */
1008	+  decide(playerId: string, requestId: string, decision: D, applied: boolean): void {
1009	+    const book = this.bookOf(playerId);
1010	+    if (applied) {
1011	+      book.applied.set(requestId, decision);
1012	+      return;
1013	+    }
1014	+    book.refused.set(requestId, decision);
1015	+    if (book.refused.size > KEPT_SHOP_REFUSALS) book.refused.delete(book.refused.keys().next().value!);
1016	+  }
1017	+
1018	+  forget(playerId: string): void {
