1020	+  }
1021	+}
1022	+
1023	+/** The ledger's decided purchase refusals: the ones it keeps, so a retry is refused the same way. */
1024	+const PURCHASE_REFUSALS: readonly string[] = ["player-in-duel", "player-disconnected", "tonic-limit", "insufficient-gold"];
1025	+
1026	+/**
1027	+ * A tonic purchase as the ledger decided it (`purchase` under `ledgerRequestId("tonic", id)`): bought, with the price and
1028	+ * the tonics now carried, or refused with the ledger's decided refusal. The room asks only for a player in the match
1029	+ * with a fresh namespaced id, so any other answer (malformed, stale, an unknown or departed player, a `duplicate`) is a
1030	+ * broken invariant: it throws, and the world tick faults (§12).
1031	+ */
1032	+export function tonicPurchaseOf(result: PurchaseResult): TonicPurchaseDecision {
1033	+  if (result.ok) return { outcome: "bought", price: result.purchase!.price, tonics: result.purchase!.tonicsAfter };
1034	+  if (result.refusal !== null && PURCHASE_REFUSALS.includes(result.refusal.rejection)) return { outcome: "refused", reason: result.refusal.rejection as TonicPurchaseRefusalName };
