1200	+/** A crate floats as a square of this half-size (sub-units) around its tile's centre; a hull overlapping it touches it. */
1201	+export const CRATE_HALF_SIZE = 64;
1202	+/** A tile is on an island's route when a path through it is at most this much longer than the island's shortest route. */
1203	+const ROUTE_SLACK = 1.15;
1204	+/** Tiles (Euclidean, between centres) a crate keeps from every dock, spawn slot and what the tests sail on. */
1205	+export const CRATE_KEEP_CLEAR_TILES = 5;
1206	+/** Tiles (Euclidean) between any two crates. */
1207	+export const CRATE_SPACING_TILES = 20;
1208	+
1209	+export interface SupplySite {
1210	+  /** The ledger's supply-cache id, and the crate's key in the synced state. */
1211	+  readonly id: string;
1212	+  /** The island whose route it lies on. */
1213	+  readonly island: number;
1214	+  readonly tileX: number;
1215	+  readonly tileY: number;
1216	+  /** Its tile's centre, in sub-units. */
1217	+  readonly x: number;
1218	+  readonly y: number;
1219	+}
1220	+
1221	+/**
1222	+ * The crates' sites: for each island in order, the navigable tile closest to halfway along its route to the hub (every
1223	+ * crossing between islands runs through the hub), among the tiles on a near-shortest path (within `ROUTE_SLACK`) that
1224	+ * keep `CRATE_KEEP_CLEAR_TILES` from the docks, spawn slots and test lanes (`keepClearZones`) and
1225	+ * `spacing` tiles (`CRATE_SPACING_TILES`) from the crates before them. Ties go to the northernmost, then westernmost tile. Throws when
1226	+ * an island has no such tile, so a map change that leaves no room fails its unit test.
1227	+ */
1228	+export function supplySites(map: SeaMapDefinition, count = SUPPLY_CRATE_COUNT, spacing = CRATE_SPACING_TILES): SupplySite[] {
1229	+  const key = `${count}:${spacing}`;
1230	+  const cached = siteCache.get(map)?.get(key);
1231	+  if (cached !== undefined) return [...cached];
1232	+  const sites = findSupplySites(map, count, spacing);
1233	+  const byKey = siteCache.get(map) ?? new Map<string, readonly SupplySite[]>();
1234	+  byKey.set(key, sites);
1235	+  siteCache.set(map, byKey);
1236	+  return [...sites];
1237	+}
1238	+
1239	+/** The sites found per map, count and spacing: the search reads every tile's paths, so each room reuses the first result. */
1240	+const siteCache = new WeakMap<SeaMapDefinition, Map<string, readonly SupplySite[]>>();
1241	+
1242	+function findSupplySites(map: SeaMapDefinition, count: number, spacing: number): SupplySite[] {
1243	+  const width = map.widthTiles;
1244	+  const hubCosts = seaPathCosts(map, map.hub.tileX, map.hub.tileY);
1245	+  const zones = keepClearZones(map).flatMap((zone) => zone.tiles);
1246	+  const far = (tileX: number, tileY: number, points: readonly { tileX: number; tileY: number }[], tiles: number) =>
1247	+    points.every((point) => (point.tileX - tileX) ** 2 + (point.tileY - tileY) ** 2 >= tiles * tiles);
1248	+  const sites: SupplySite[] = [];
1249	+  const size = map.subUnitsPerTile;
1250	+  for (let island = 0; sites.length < count; island++) {
1251	+    const docks = map.docks.filter((dock) => dock.island === island);
1252	+    if (docks.length === 0) throw new Error(`${map.name}: no island ${island} for supply crate ${sites.length}`);
1253	+    const dockCosts = docks.map((dock) => seaPathCosts(map, dock.tileX, dock.tileY));
1254	+    const route = Math.min(...docks.map((dock) => hubCosts[dock.tileY * width + dock.tileX]!));
1255	+    let best: { tileX: number; tileY: number; score: number } | undefined;
1256	+    for (let tileY = 0; tileY < map.heightTiles; tileY++) {
1257	+      for (let tileX = 0; tileX < width; tileX++) {
1258	+        if (!isNavigable(map, tileX, tileY)) continue;
1259	+        const index = tileY * width + tileX;
1260	+        const fromDock = Math.min(...dockCosts.map((costs) => costs[index]!));
1261	+        const toHub = hubCosts[index]!;
1262	+        if (fromDock + toHub > route * ROUTE_SLACK) continue;
1263	+        if (!far(tileX, tileY, zones, CRATE_KEEP_CLEAR_TILES) || !far(tileX, tileY, sites, spacing)) continue;
1264	+        const score = Math.abs(fromDock - toHub);
1265	+        if (best === undefined || score < best.score) best = { tileX, tileY, score };
1266	+      }
1267	+    }
1268	+    if (best === undefined) throw new Error(`${map.name}: no room for a supply crate on island ${island}'s route`);
1269	+    const half = Math.floor(size / 2);
1270	+    sites.push({ id: `crate-${sites.length}`, island, tileX: best.tileX, tileY: best.tileY, x: best.tileX * size + half, y: best.tileY * size + half });
1271	+  }
1272	+  return sites;
1273	+}
1274	+
1275	+/** Whether a ship's hull (a square of `hullHalfSize` around it) overlaps a crate. */
1276	+export function touchesCrate(site: Pick<SupplySite, "x" | "y">, ship: { readonly x: number; readonly y: number }, hullHalfSize: number): boolean {
1277	+  const reach = hullHalfSize + CRATE_HALF_SIZE;
1278	+  return Math.abs(ship.x - site.x) <= reach && Math.abs(ship.y - site.y) <= reach;
1279	+}
1280	+
1281	+/**
1282	+ * The crates claimed on one tick: for each unclaimed crate, the ship that gets it among those touching it, the lowest
1283	+ * player id first (ships are kept in join order, which must not decide), so two ships reaching one crate on the same
1284	+ * tick always resolve the same way. A ship may claim several crates on one tick.
1285	+ */
1286	+export function crateClaims(
1287	+  sites: readonly SupplySite[],
1288	+  claimed: ReadonlySet<string>,
1289	+  ships: readonly { readonly id: string; readonly x: number; readonly y: number }[],
1290	+  hullHalfSize: number,
1291	+): { readonly crateId: string; readonly playerId: string }[] {
1292	+  const byId = [...ships].sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
1293	+  return sites.flatMap((site) => {
1294	+    if (claimed.has(site.id)) return [];
1295	+    const first = byId.find((ship) => touchesCrate(site, ship, hullHalfSize));
1296	+    return first === undefined ? [] : [{ crateId: site.id, playerId: first.id }];
1297	+  });
1298	+}
