781	  /** One frame of the clock, whether or not the test-only pause holds it (`stepWorldTicks` runs it then). */
782	  private stepFrame(): void {
783	    const frame = this.simulation.frame + 1;
784	    const inputs: Record<string, PlayerInput> = {};
785	    const playing = this.inPlay();
786	    const held = this.heldPlayers();
787	    for (const [sessionId, gate] of this.gates) {
788	      // No control before the start or after the end; a reserved or respawning ship ignores its player's helm (§6).
789	      if (!playing || held.has(sessionId)) inputs[sessionId] = NEUTRAL_INPUT;
790	      // A lapsed client gets no entry: its ship sails as neutral, but keeps its mooring throttle until real input.
791	      else if (!gate.lapsedAt(frame)) inputs[sessionId] = gate.inputAt(frame);
792	    }
793	    this.simulation = step(this.config, this.simulation, inputs);
794	    this.worldLog?.push({ inputs, drinks: [] });
795	    for (const duel of this.seaDuels.values()) duel.machine.advance();
796	    if (!isWorldStep(this.simulation.frame)) return;
797	    const tick = this.simulation.worldTick;
798	    try {
799	      this.worldTick(frame, tick, held, playing);
800	    } catch (error) {
801	      this.fault(tick, error);
802	    }
803	    for (const [id, gate] of this.gates) {
804	      const gap = gate.worldStepTaken(frame);
805	      if (gap !== undefined) console.warn(`match ${this.state.code}: ${id}'s held hold button lapsed after ${Math.round((gap * 1000) / STEPS_PER_SECOND)} ms without input`);
806	    }
807	    this.checkInvariants(tick);
808	    this.mirror();
809	    if (this.pauseAt !== undefined && tick >= this.pauseAt) {
810	      this.pauseAt = undefined;
811	      this.paused = true;
812	    }
813	  }
814	
815	  /**
816	   * One world tick (20 Hz), in a fixed order. While the match runs: the ledger's clock (closed theft windows settle),
817	   * the §12 timers, then §5's order: the encounters (accepted reservations first), the ledger's holds, the claim
818	   * channel, the match flow (with this tick's claim end and accomplishments), and the reveals. Before control start
819	   * only the timers and the flow run (the lobby and the ready countdown); once the match has ended nothing changes but
820	   * the settled duels' lobbies leaving their fighters' views.
821	   */
822	  private worldTick(frame: number, tick: number, held: ReadonlySet<string>, playing: boolean): void {
823	    if (this.flow.end !== null) {
824	      this.closeShownDuels(tick);
825	      return;
826	    }
827	    if (this.faultNext) {
828	      this.faultNext = false;
829	      throw new Error("test-only fault injected into the world tick");
830	    }
831	    // The ledger's clock first: choice windows that closed settle with the default theft.
832	    this.ledgerStep("advanceLedger", advanceLedger(this.ledger, { tick }));
833	    this.runAbsences(tick);
834	    let claimEnd: FlowReport | undefined;
835	    if (playing) {
836	      this.stepEncounters(frame, held);
837	      // §11: the ships touching an unclaimed supply crate after this tick's sailing, the lowest player id first.
838	      this.stepCrates(tick);
839	      // Where everyone is now, for the ruins: casting off or entering a duel closes a session (§3).
840	      for (const ship of this.simulation.ships) this.syncRuinPresence(ship.id);
841	      // §9's eating, with this tick's reservations: a duel reserved on this tick interrupts it.
842	      this.stepFruits(frame, tick);
843	      this.stepChannels(frame, tick);
844	      claimEnd = this.stepClaim(frame, tick);
845	      // §11's shop: this tick's tonic purchases (moored at a dock now) and drinks (at sea now, after the sailing step).
846	      this.stepShop(tick);
847	    }
848	    this.noteSettlements();
849	    if (playing) this.reportAccomplishments(tick);
850	    this.stepFlow(tick, claimEnd);
851	    if (this.flow.controlStartTick !== null && this.flow.end === null) this.stepReveals(tick);
852	  }
853	
854	  /** Player control has started and the match has not ended (§2's departure and exploration). */
855	  private inPlay(): boolean {
856	    return this.flow.phase === "departure" || this.flow.phase === "exploration";
857	  }
858	
859	  /** Players whose ship is reserved for a duel (until it is settled) or waits out of the world to respawn. */
860	  private heldPlayers(): Set<string> {
861	    const held = new Set<string>();
862	    for (const duel of this.encounters.duels) for (const id of duel.players) held.add(id);
863	    for (const player of this.encounters.players) if (player.respawn !== null) held.add(player.id);
864	    return held;
865	  }
866	
867	  /** The duel at sea a session fights in (until its lobby is removed). */
868	  private duelOfSession(sessionId: string): SeaDuel | undefined {
869	    for (const duel of this.seaDuels.values()) if (duel.players.includes(sessionId)) return duel;
870	    return undefined;
871	  }
872	
873	  /** Takes a settled duel's lobby out of its fighters' views. */
874	  private closeSeaDuel(duel: SeaDuel): void {
875	    this.state.duels.delete(duel.key);
876	    this.seaDuels.delete(duel.id);
877	  }
878	
879	  /**
880	   * §12 on the world tick: a fighter away from an unfinished duel for `duelAbsenceTicks` forfeits it (the duel goes on
881	   * to its settlement; they keep their seat); a disconnected player whose reservation deadline has come is removed,
882	   * their remaining rubbings going into a cache at the respawn dock the encounter rules would choose.
883	   */
884	  private runAbsences(tick: number): void {
885	    for (const [id, away] of this.away) {
886	      if (away.duelAbsentSince === undefined) continue;
887	      const duel = this.duelOfSession(id);
888	      if (duel === undefined || duel.machine.outcome !== undefined) away.duelAbsentSince = undefined;
889	      else if (tick - away.duelAbsentSince >= this.tuning.duelAbsenceTicks) {
890	        duel.machine.leave(id);
891	        away.duelAbsentSince = undefined;
892	      }
893	    }
894	    for (const player of this.ledger.players) {
895	      if (player.status !== "disconnected" || player.reservationDeadline === null || tick < player.reservationDeadline) continue;
896	      const position = this.respawnDockOf(player.id);
897	      this.ledgerStep("expireReservation", expireReservation(this.ledger, { playerId: player.id, tick, position }));
898	      // §12: an expired reservation releases the seat, which the flow counts as leaving.
899	      this.flowReports.push({ kind: "leave", playerId: player.id });
900	      const duel = this.duelOfSession(player.id);
901	      if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(player.id);
902	      const away = this.away.get(player.id);
903	      this.removePlayer(player.id);
904	      // The socket's seat goes too: Colyseus then calls onLeave, which finds the player already gone.
905	      if (typeof away?.reconnection?.reject === "function") away.reconnection.reject(false);
906	    }
907	  }
908	
909	  /** §12 expiry: the dock the encounter rules would respawn this player at, from where their ship is (or waits). */
910	  private respawnDockOf(id: string): { x: number; y: number } {
911	    const ship = this.simulation.ships.find((each) => each.id === id);
912	    const respawn = this.encounters.players.find((each) => each.id === id)?.respawn ?? null;
913	    const from = respawn !== null ? { x: respawn.x, y: respawn.y } : ship !== undefined ? { x: ship.x, y: ship.y } : dockCentre(this.config.map, 0);
914	    const waiting = new Set(this.encounters.players.filter((each) => each.respawn !== null).map((each) => each.id));
915	    const opponents = this.simulation.ships.filter((each) => each.id !== id && !waiting.has(each.id)).map((each) => ({ x: each.x, y: each.y }));
916	    const point = this.encounterConfig.modes.ship.rules.respawnPoint({ encounter: from, own: from, opponents, clearRadius: this.encounterConfig.respawnClearRadius });
917	    return { x: point.x, y: point.y };
918	  }
919	
920	  /** §12 quit: a duel in progress is forfeited (in the ledger and in the fight), the rest goes to the nearest dock. */
921	  private quit(id: string): void {
922	    const ship = this.simulation.ships.find((each) => each.id === id);
923	    const at = ship ?? dockCentre(this.config.map, 0);
924	    const position = dockCentre(this.config.map, nearestDockBySea(this.config.map, at.x, at.y));
925	    this.ledgerStep("quitPlayer", quitPlayer(this.ledger, { playerId: id, tick: this.simulation.worldTick, position }));
926	    const duel = this.duelOfSession(id);
927	    if (duel !== undefined && duel.machine.outcome === undefined) duel.machine.leave(id);
928	  }
929	
930	  /** The ship and the input channel of a player who has left the ledger's match. */
931	  private removePlayer(id: string): void {
932	    this.setRuinPresence(id, null, false);
933	    this.ruinRequests.forget(id);
934	    this.ruinRate.delete(id);
935	    this.journal.forget(id);
936	    this.rumors.forget(id);
937	    this.rumorRate.delete(id);
938	    this.rumorOffers.delete(id);
939	    this.tonicPurchases.forget(id);
940	    this.tonicUses.forget(id);
941	    this.shopRate.delete(id);
942	    this.knownIslands.delete(id);
943	    this.fruitRate.delete(id);
944	    this.simulation = removeShip(this.simulation, id);
945	    this.gates.delete(id);
946	    this.away.delete(id);
947	    this.choiceRate.delete(id);
948	  }
